import argparse
import csv
import json
from datetime import date


def parse_args():
    parser = argparse.ArgumentParser()
    parser.add_argument("sales_csv")
    parser.add_argument("--format", choices=("text", "json"), default="text")
    parser.add_argument("--since", type=date.fromisoformat, metavar="YYYY-MM-DD")
    return parser.parse_args()


def summarize(path, since=None):
    rows = 0
    total_revenue = 0
    total_tax = 0
    by_region = {}
    by_product = {}

    with open(path, newline="") as sales_file:
        reader = csv.reader(sales_file)
        next(reader, None)
        for row in reader:
            if len(row) < 5:
                continue
            if since is not None:
                try:
                    sale_date = date.fromisoformat(row[0])
                except ValueError:
                    continue
                if sale_date < since:
                    continue
            try:
                units = int(row[3])
                price = float(row[4])
            except ValueError:
                continue

            amount = units * price
            if units >= 50:
                amount -= amount * 0.1
            elif units >= 10:
                amount -= amount * 0.05

            region = row[1]
            if region == "north":
                tax_rate = 0.07
            elif region == "south":
                tax_rate = 0.05
            elif region == "east":
                tax_rate = 0.06
            elif region == "west":
                tax_rate = 0.08
            else:
                tax_rate = 0

            total_revenue += amount
            total_tax += amount * tax_rate
            by_region[region] = by_region.get(region, 0) + amount
            by_product[row[2]] = by_product.get(row[2], 0) + amount
            rows += 1

    top_product = None
    top_value = 0
    for product, amount in by_product.items():
        if amount > top_value:
            top_product, top_value = product, amount

    return {
        "rows": rows,
        "total_revenue": total_revenue,
        "total_tax": total_tax,
        "by_region": by_region,
        "by_product": by_product,
        "top_product": top_product,
    }, top_value


def print_text(report, top_value):
    print("SALES REPORT")
    print("============")
    print("Rows: " + str(report["rows"]))
    print("Total revenue: " + str(round(report["total_revenue"], 2)))
    print("Total tax: " + str(round(report["total_tax"], 2)))
    print("")
    print("By region:")
    for key in sorted(report["by_region"]):
        print("  " + key + ": " + str(round(report["by_region"][key], 2)))
    print("")
    print("By product:")
    for key in sorted(report["by_product"]):
        print("  " + key + ": " + str(round(report["by_product"][key], 2)))
    print("")
    print("Top product: " + str(report["top_product"]) + " (" + str(round(top_value, 2)) + ")")


def main():
    args = parse_args()
    report, top_value = summarize(args.sales_csv, args.since)
    if args.format == "json":
        result = dict(report)
        result["total_revenue"] = round(result["total_revenue"], 2)
        result["total_tax"] = round(result["total_tax"], 2)
        result["by_region"] = {k: round(v, 2) for k, v in result["by_region"].items()}
        result["by_product"] = {k: round(v, 2) for k, v in result["by_product"].items()}
        print(json.dumps(result))
    else:
        print_text(report, top_value)


if __name__ == "__main__":
    main()
